const items = $input.all();
const webhookData = $('Webhook - Thread ID').item.json.body;

if (items.length === 0) {
  return [{ json: { summary: 'No messages found in thread.', messageCount: 0 } }];
}

// Sort by date
const sorted = items.sort((a, b) => new Date(a.json.date || 0) - new Date(b.json.date || 0));

let keyPoints = [];
let participants = new Set();
let threadSubject = '';

for (let i = 0; i < sorted.length; i++) {
  const msg = sorted[i].json;
  const from = msg.from || 'Unknown';
  const body = (msg.textPlain || msg.snippet || '').trim();
  const date = msg.date ? new Date(msg.date).toLocaleString() : '';

  participants.add(from);
  if (i === 0) threadSubject = msg.subject || 'No Subject';

  // Extract key sentences (first 2-3 meaningful lines)
  const lines = body.split('\n').filter(l => {
    const trimmed = l.trim();
    return trimmed.length > 20 && !trimmed.startsWith('>') && !trimmed.startsWith('On ') && !trimmed.includes('wrote:');
  });

  const keyContent = lines.slice(0, 3).join(' ').substring(0, 300);
  if (keyContent) {
    keyPoints.push(`**${from}** (${date}):\n${keyContent}`);
  }
}

const summary = `# Thread Summary: ${threadSubject}\n\n` +
  `**Messages:** ${sorted.length}\n` +
  `**Participants:** ${[...participants].join(', ')}\n\n` +
  `## Key Points:\n\n${keyPoints.map((p, i) => `${i + 1}. ${p}`).join('\n\n')}`;

return [{
  json: {
    summary: summary,
    threadSubject: threadSubject,
    messageCount: sorted.length,
    participants: [...participants].join(', '),
    forwardTo: webhookData.forwardTo || '',
    threadId: webhookData.threadId,
    summarizedAt: new Date().toISOString()
  }
}];
